"use strict";(globalThis.webpackChunkgrc||=[]).push([[3115],{61882(e){e.exports=JSON.parse('{"citeKey":"devarajan2020hcl","slug":"devarajan-2020-hcl-d2f4","title":"HCL: Distributing Parallel Data Structures in Extreme Scales","authors":["H. Devarajan","A. Kougkas","K. Bateman","X.-H. Sun"],"venue":"IEEE International Conference on Cluster Computing (CLUSTER\'20), Sept. 14-17, 2020","type":"Conference","entryType":"inproceedings","date":"September, 2020","year":2020,"era":"iit","month":9,"doi":"10.1109/cluster49012.2020.00035","abstract":"Most parallel programs use irregular control flow and data structures, which are perfect for one-sided communication paradigms such as MPI or PGAS programming languages. However, these environments lack the presence of efficient function-based application libraries that can utilize popular communication fabrics such as TCP, Infinity Band (IB), and RDMA over Converged Ethernet (RoCE). Additionally, there is a lack of high-performance data structure interfaces. We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues. HCL uses a RPC over RDMA technology that implements a novel procedural programming paradigm. In this paper, we argue a RPC over RDMA technology can serve as a high-performance, flexible, and co-ordination free backend for implementing complex data structures. Evaluation results from testing real workloads shows that HCL programs are 2x to 12x faster compared to BCL, a state-of-the-art distributed data structure library.","hasAbstract":true,"lede":"We present Hermes Container Library (HCL), a high-performance distributed data structures library that offers high-level abstractions including hash-maps, sets, and queues.","links":{"pdf":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4.pdf","slides":"https://grc.iit.edu/papers/2020/devarajan-2020-hcl-d2f4-slides.pdf"},"tags":["Distributed Data Structure","RPC over RDMA","Hybrid Data Access Model","HPC Data Containers","Hermes"],"_projectIds":["hermes","iris"],"grcSelected":false,"status":"published","visibility":"public","projectIds":["hermes","iris"],"memberAuthors":["devarajan-hariharan","kougkas-anthony","bateman-keith","sun-xian-he"],"funding":[{"agency":"NSF","award":"OAC-1835764","projectId":"hermes"},{"agency":"NSF","award":"CSR-1814872","projectId":"iris"}]}')}}]);